const { withAppBuildGradle } = require('expo/config-plugins');

// Release signing for local builds (DECISIONS #135). `android/` is generated by prebuild and
// out of git, so the signing setup lives here. The key stays out of git too, in the workspace
// folder next to this repo: `quadra-release.properties` (QUADRA_RELEASE_STORE_FILE, relative to
// that file, plus _STORE_PASSWORD, _KEY_ALIAS, _KEY_PASSWORD) and the keystore it names.
// Without them a local release build (APK or AAB) fails instead of falling back to the debug key.
// EAS builds sign with the EAS credentials and skip the check.
const MARKER = '// quadra-release-signing';

const GRADLE = `
${MARKER} (plugins/withReleaseSigning.js)
def quadraReleaseFile = new File(projectRoot, '../quadra-release.properties')
def quadraReleaseProps = new Properties()
if (quadraReleaseFile.exists()) {
    quadraReleaseFile.withInputStream { quadraReleaseProps.load(it) }
}
def quadraReleaseStore = quadraReleaseProps['QUADRA_RELEASE_STORE_FILE'] ?
    new File(quadraReleaseFile.parentFile, quadraReleaseProps['QUADRA_RELEASE_STORE_FILE']) : null
def hasQuadraReleaseKey = quadraReleaseStore != null && quadraReleaseStore.exists()

android {
    if (hasQuadraReleaseKey) {
        signingConfigs {
            quadraRelease {
                storeFile quadraReleaseStore
                storePassword quadraReleaseProps['QUADRA_RELEASE_STORE_PASSWORD']
                keyAlias quadraReleaseProps['QUADRA_RELEASE_KEY_ALIAS']
                keyPassword quadraReleaseProps['QUADRA_RELEASE_KEY_PASSWORD']
            }
        }
        buildTypes.release.signingConfig signingConfigs.quadraRelease
    }
}

gradle.taskGraph.whenReady { graph ->
    def releaseTask = graph.allTasks.any { it.project == project && it.name ==~ /(assemble|bundle|package)Release/ }
    if (releaseTask && !hasQuadraReleaseKey && System.getenv('EAS_BUILD') == null) {
        throw new GradleException("Release build without the release key: put quadra-release.properties and its keystore in " +
            new File(projectRoot, '..').canonicalPath + " (DECISIONS #135). The debug key is never used for release.")
    }
}
`;

function addReleaseSigning(buildGradle) {
  return buildGradle.includes(MARKER) ? buildGradle : `${buildGradle.trimEnd()}\n${GRADLE}`;
}

module.exports = (config) =>
  withAppBuildGradle(config, (cfg) => {
    cfg.modResults.contents = addReleaseSigning(cfg.modResults.contents);
    return cfg;
  });
module.exports.addReleaseSigning = addReleaseSigning;
